import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs,[[0,1,4,11,3],[2,3,3,2,5],[4,8,2,10,8],[3,2,11,3,4],[10,6,10,10,4]]))
tr=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(tr[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def incident(p,k):
 pos={j:p.index(j)+1 for j in jobs}
 if pos['A']>pos['D']: return None
 if k=='rain':
  if pos['D']==1 or pos['A']==1: return None
  penalty=6*(pos['C']-1)
 elif k=='road':
  if pos['C']==4 or pos['E']==2: return None
  penalty=6*max(0,pos['D']-3)
 else:
  if pos['A']==1 or pos['B']==1: return None
  penalty=10*max(0,pos['E']-2)
 return nominal(p)+penalty
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'): continue
 finals=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p); q[i],q[j]=q[j],q[i]
  finals.append((tuple(q),1))
 repairs={}
 for k in ['rain','road','lift']:
  choices=[(incident(q,k)+fee,''.join(q)) for q,fee in finals if incident(q,k) is not None]
  if not choices: break
  repairs[k]=min(choices)
 if len(repairs)==3:
  results.append((nominal(p)+max(v[0] for v in repairs.values()),''.join(p),repairs))
results.sort()
best=results[0]
answer={'roster':best[1],'score':best[0],'repairs':{k:v[1] for k,v in best[2].items()},'repair_costs':{k:v[0] for k,v in best[2].items()},'feasible_count':len(results),'next_score':min(v[0] for v in results if v[0]>best[0])}
assert len(results)==len(set(r[1] for r in results))
print(json.dumps(answer))
print('best publication nominal:',nominal(tuple(best[1])))
print('top five:',results[:5])

